from lib import *
S = SS('h33')
steps = [
    step("客户端 → A → B,B 干活 500 ms;客户端超时和 A 调 B 时自己加的超时各取不同的值(A 调 B 用的是收到的 ctx,再套一层自己的超时)。客户端 1000 ms、A 无超时:成功,用了 503.5 ms,B 在线上看到 grpc-timeout 999514u(999514 微秒,约 999.5 ms);客户端 1000 ms、A 的超时 300 ms:DeadlineExceeded,304.2 ms 就返回,B 看到 299990u,B 被取消 1 次——A 的 300 ms 先到期,客户端还有 700 ms 没用上也得到 DeadlineExceeded;客户端 200 ms、A 的超时 1000 ms:202.1 ms 返回 DeadlineExceeded,B 看到 197163u——A 的 1000 ms 比客户端的剩余时间长,没有起作用,取的是客户端的;客户端无超时、A 也无:成功,B 看到 grpc-timeout (无)。各层超时取最小的,而且最内层的超时对客户端表现为同样的 DeadlineExceeded,客户端分不清是自己的还是下游的。", t=tl(S(1)), done=lidx(S(1), '客户端超时 无'), mark=lidx(S(1), 'A 调 B 的超时 300 ms'), b=bars([['客户端 1000 + A 300:返回用时 ms', 304.2, '304.2'], ['客户端 200 + A 1000:返回用时 ms', 202.1, '202.1'], ['客户端 1000 + A 无:返回用时 ms(成功)', 503.5, '503.5']], 520, mark=[0, 1], done=[2]), kv=KV([['规则', '各层超时取最小的'], ['内层先到期', '客户端也得到 DeadlineExceeded'], ['内层比外层剩余时间还长', '不起作用']], ['规则'])),
    step("deadline 沿着调用链往下传,每一跳都在变小。客户端设 1000 ms:A 在调用 B 之前先耗掉 0 ms:客户端→A 的 grpc-timeout 是 999419u,A→B 是 999400u,B 看到剩余 999 ms;A 先耗 200 ms:A→B 变成 797916u,B 看到剩余 797 ms;A 先耗 600 ms:A→B 397083u,B 看到剩余 396 ms。客户端不设超时:整条链上都没有 grpc-timeout 头,B 看到没有 deadline。传的是“剩余时间”(相对值),每一跳按当前时刻重新计算,所以排队或前面的耗时都会被扣掉。", t=tl(S(2)), done=lidx(S(2), '客户端不设超时'), mark=lidx(S(2), 'A 先耗   0 ms'), b=bars([['A 先耗 0:B 看到剩余 ms', 999, '999'], ['A 先耗 200:B 看到剩余 ms', 797, '797'], ['A 先耗 600:B 看到剩余 ms', 396, '396']], 1000, mark=[0], done=[1, 2]), kv=KV([['传的是', '剩余时间(grpc-timeout 头)'], ['每一跳', '扣掉已经用掉的时间'], ['客户端不设', '整条链都没有 deadline']], ['传的是'])),
    step("A 重试 B:每次尝试的超时 400 ms,最多 3 次,B 干活 1000 ms(每次都超时)。客户端超时 1000 ms:A 尝试了 3 次(B 收到 3 次、被取消 3 次),客户端在 1002.1 ms 得到 DeadlineExceeded——第三次尝试被客户端的 deadline 截断(400+400 之后只剩约 200 ms);客户端超时 2000 ms:A 同样试了 3 次,客户端 1209.1 ms 得到 DeadlineExceeded(3 × 400 ms + 退出);客户端不设超时:也是 3 次,1206.2 ms。客户端的 deadline 是总预算,重试的次数和每次的超时要放在这个预算之内,否则最后的尝试会被截断;并且每一次失败的尝试,B 都白做了工作(被取消前)。", t=tl(S(3)), done=lidx(S(3), '客户端超时 无'), mark=lidx(S(3), '客户端超时 1000 ms'), b=bars([['客户端 1000:用时 ms', 1002.1, '1002.1'], ['客户端 2000:用时 ms', 1209.1, '1209.1'], ['客户端无超时:用时 ms', 1206.2, '1206.2']], 1250, mark=[0], done=[1, 2]), kv=KV([['3 次尝试 × 400 ms', '约 1200 ms'], ['客户端 1000 ms', '第三次被截断,1002.1 ms'], ['B 收到', '每次 3 次,都被取消']], ['客户端 1000 ms'])),
    step("A 调 B 时不传收到的 ctx(用 context.Background() 加 2 秒超时)的后果:客户端 200 ms 就放弃了,B 的活还要做 1500 ms。A 传 ctx:客户端 202.1 ms 得到 DeadlineExceeded,放弃后 100 ms B 已被取消 1 次,1.8 秒后 B 做完 0 次;A 用 Background:客户端同样 202.1 ms 得到 DeadlineExceeded,但放弃后 100 ms B 被取消 0 次,1.8 秒后 B 做完了 1 次——客户端已经走了,B 仍然把活做完了,浪费的工作。凡是转发调用,一定要把收到的 ctx 传下去(第 5 篇、第 6 篇)。", t=tl(S(4)), done=lidx(S(4), 'A 用 Background'), mark=lidx(S(4), 'A 传 ctx'), b=bars([['A 传 ctx:1.8 秒后 B 做完', 0, '0'], ['A 用 Background:1.8 秒后 B 做完', 1, '1']], 1.2, mark=[1], done=[0]), kv=KV([['A 传 ctx', 'B 被取消,不浪费'], ['A 用 Background', 'B 白白做完 1500 ms 的活'], ['客户端', '两种情况都是 202.1 ms DeadlineExceeded']], ['A 用 Background'])),
]
A = mkarth('h33', 33, 'gRPC,超时,deadline,调用链,grpc-timeout,重试预算,Go,真实验证,动画演示',
    '实测 gRPC 调用链上的超时叠加:各层取最小;内层比外层剩余时间还长的超时不起作用;deadline 以剩余时间的形式(grpc-timeout 头)每一跳递减;A 重试 B 3 次会吃掉外层的预算;转发调用不传 ctx 会让下游白做工作。',
    '客户端、网关、服务各设一个超时会怎样?链路一长,deadline 是怎么一路传下去的?重试和超时叠在一起时谁说了算?这篇用 客户端 → A → B 的三层调用逐项实测,线上的 grpc-timeout 头也一并抓出来。',
    [('304.2 ms', '客户端 1000 ms、A 调 B 超时 300 ms 时,客户端实际得到 DeadlineExceeded 的时间'), ('999 → 797 → 396 ms', 'A 在调用 B 前先耗 0/200/600 ms 时,B 看到的剩余 deadline'), ('做完 1 次', '客户端 200 ms 放弃后,A 用 Background 调 B,B 仍然把 1500 ms 的活做完')],
    [('取最小', '<p>调用链上每一层的超时叠加起来,谁先到期谁说了算。内层的超时比外层剩余时间还长就没有作用。无论哪一层先到期,客户端看到的都是 DeadlineExceeded,分不清是自己的还是下游的,要靠日志、追踪或错误详情区分。</p>'),
     ('传的是剩余时间', '<p>gRPC 在 grpc-timeout 头里传剩余时间,每一跳按当前时刻重新计算,前面耗掉的时间自然被扣掉。没设 deadline 就一路都没有。</p>'),
     ('重试要放进预算', '<p>外层的 deadline 是总预算。重试的次数和每次的超时加起来超出时,最后一次会被截断,而每次失败的尝试下游都做了(部分)工作。</p>'),
     ('转发要传 ctx', '<p>转发下游调用必须用收到的 ctx(或它的派生),否则上游放弃之后,下游仍把活做完。</p>')],
    steps,
    [ENV_H + '。链路是本机的三个进程内服务(客户端 → A → B),A 和 B 都是 grpc 服务器,线上 grpc-timeout 头来自两个抓包代理(分别在客户端→A、A→B 上);grpc-timeout 头的单位是“u”表示微秒;所有时间是本机测量,B 的“活”是带 ctx 监听的 sleep',
     '没有验证:网关(HTTP→gRPC)层的超时与 Grpc-Timeout 头(第 29 篇测过一部分);服务网格或代理(Envoy)的超时叠加;客户端的 WithTimeout 与 per-call 超时的区别;deadline 在跨语言调用链上的传递;gRPC 重试策略(service config)与应用层重试的叠加(第 18 篇);服务端自己没有 ctx 监听时的行为(第 31 篇)'],
    '超时叠加')
